import { flushPromises, mount } from '@vue/test-utils';
import App from './App.vue';

// The stand-in API answers after 600 ms; fake timers skip the wait.
async function mountLoaded() {
  const wrapper = mount(App);
  jest.advanceTimersByTime(600);
  await flushPromises();
  return wrapper;
}

const titles = (wrapper) => wrapper.findAll('.issue-title').map((title) => title.text());

beforeEach(() => {
  jest.useFakeTimers();
});

afterEach(() => {
  jest.useRealTimers();
});

describe('App', () => {
  it('lists the open issues once they load', async () => {
    const wrapper = await mountLoaded();

    expect(titles(wrapper)).toHaveLength(5);
    expect(wrapper.find('.issue-count').text()).toBe('5 open issues');
  });

  it('filters the loaded issues by label without loading them again', async () => {
    const wrapper = await mountLoaded();

    await wrapper.findAll('.label-filter')[1].trigger('click');

    expect(wrapper.find('.issues-state').exists()).toBe(false);
    expect(titles(wrapper)).toEqual(['Dark mode resets after sign-in', 'Search ignores accented letters']);
    expect(wrapper.find('.issue-count').text()).toBe('2 open issues');
    expect(wrapper.findAll('.label-filter')[1].attributes('aria-pressed')).toBe('true');
  });

  it('says 1 open issue for a single match', async () => {
    const wrapper = await mountLoaded();

    await wrapper.findAll('.label-filter')[3].trigger('click');

    expect(titles(wrapper)).toEqual(['Document the webhook retry policy']);
    expect(wrapper.find('.issue-count').text()).toBe('1 open issue');
  });
});
